UPDATE public.story_nodes SET title='The Dragon Master''s Call', description='You unearth a strange worm in the onion field, and King Roland''s soldier drafts you on the spot.', body_text='Dawn breaks over the onion field. As you dig, something glows in the soil — a worm, watching you. Before you can speak, a soldier of King Roland rides up and points at you: "You. The king needs a dragon handler."', speaker='Narrator', options='[{"label":"Follow the soldier without protest","next_node":"Node_2","state_changes":{"Courage":0}},{"label":"Show your fear and resist","next_node":"Node_2","state_changes":{"Courage":5}}]'::jsonb WHERE chapter_id='dragon_master' AND node_key='Node_1';

UPDATE public.story_nodes SET title='Meeting Vulcan', description='You arrive at the castle and witness the giant red dragon Vulcan spitting fire.', body_text='The castle gates groan open. Inside the courtyard a colossal red dragon — Vulcan — rears up and unleashes a torrent of flame. Stone blackens. Guards scatter. The air itself burns.', speaker='Narrator', options='[{"label":"Hide immediately","next_node":"Node_12","state_changes":{"Courage":-5}},{"label":"Freeze in place, stunned","next_node":"Node_12","state_changes":{"Courage":0}}]'::jsonb WHERE chapter_id='dragon_master' AND node_key='Node_2';

UPDATE public.story_nodes SET title='The Worm''s Warning', description='In the worm''s cave, it warns you telepathically not to enter the tunnel.', body_text='Blue light pulses in the dark. The worm''s voice arrives without sound, straight inside your head: "Do not enter that tunnel. What waits there does not forgive."', speaker='Worm', options='[{"label":"Drag the worm along anyway","next_node":"Node_19","state_changes":{"Worm_Affinity":-10,"Courage":5}},{"label":"Leave the worm behind and go alone","next_node":"Node_19","state_changes":{"Worm_Affinity":5}}]'::jsonb WHERE chapter_id='dragon_master' AND node_key='Node_12';

UPDATE public.story_nodes SET title='Earth Magic', description='The worm uses earth magic — the power of mind — to grind the fallen boulders into dust.', body_text='The tunnel collapses. Then the worm''s eyes flare, and the fallen boulders shudder, crack, and dissolve into drifting dust. Earth magic. The power of a focused mind.', speaker='Narrator', options='[{"label":"Hug the worm with pride","next_node":"Node_20","state_changes":{"Worm_Affinity":20}},{"label":"Sink to your knees at the sight","next_node":"Node_20","state_changes":{"Courage":-5}}]'::jsonb WHERE chapter_id='dragon_master' AND node_key='Node_19';

UPDATE public.story_nodes SET title='A True Master', description='Griffith catches you, but acknowledges the worm''s power — and hints at a new threat.', body_text='Griffith''s torch finds you in the dark. He studies the worm for a long moment, then nods. "So it is true. You may be a master after all. Good — because something worse than Vulcan is stirring."', speaker='Narrator', options='[{"label":"See the ending","next_node":null,"state_changes":{}}]'::jsonb WHERE chapter_id='dragon_master' AND node_key='Node_20';